import{_ as r,o as d,c as i,a5 as n}from"./chunks/framework.CslsFoWx.js";const a="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-01-avant-part-payee.png",t="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-02-apres-part-payee.png",o="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-03-avant-addition-table.png",s="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-04-apres-addition-table.png",b=JSON.parse(`{"title":"Symbole de devise après une part d'addition (ticket Trello P2, 08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-symbole-devise-parts.md","filePath":"generated/preuves/2026-11-08-symbole-devise-parts.md","lastUpdated":null}`),p={name:"preuves/2026-11-08-symbole-devise-parts.md"};function l(c,e,m,g,u,f){return d(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="symbole-de-devise-apres-une-part-d-addition-ticket-trello-p2-08-11-2026" tabindex="-1">Symbole de devise après une part d&#39;addition (ticket Trello P2, 08/11/2026) <a class="header-anchor" href="#symbole-de-devise-apres-une-part-d-addition-ticket-trello-p2-08-11-2026" aria-label="Permalink to &quot;Symbole de devise après une part d&#39;addition (ticket Trello P2, 08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-symbole-devise-parts</code> · 4 image(s) · 0 trace(s)</p><div><p><strong>Défaut</strong> : après l&#39;encaissement d&#39;une part d&#39;addition (parts égales ou par articles, caisse ou téléphone de salle), la note de confirmation iOS affichait le code ISO — « Table T6 · Part 1/2 — reste 16,25 EUR » — au lieu du symbole du commerce (« 16,25 € »). Android était déjà correct.</p><p><strong>Cause</strong> : <code>formatMoney</code> (iOS, <code>iosApp/PosApp/Support/MoneyFormatting.swift</code>) formatait à la main « montant + code ISO », alors que son équivalent Android délègue au formateur commun <code>MoneyDisplay</code> (<code>:shared</code>, décision D10). Tous les messages iOS passant par <code>formatMoney</code> étaient touchés : note de part, refus « reste dû », dépassement hors espèces, rendu / remboursement d&#39;un retour, mouvements d&#39;espèces, écart de clôture, ardoise, remises, rapports X / Z à l&#39;écran, chiffres des alertes responsables.</p><p><strong>Correction</strong> : <code>formatMoney</code> (et <code>formatTND</code>) délèguent à <code>MoneyDisplay.format</code> — symbole local, séparateurs et décimales de la devise (« 22,50 € », « 22,500 DT »), parité Android. Les tickets imprimés (vente, X / Z, pro forma : <code>pos.shared.printing.formatAmountMinor</code> + code ISO) ne sont <strong>pas</strong> modifiés.</p><p>Capture : simulateur iPhone 16 dédié (iOS 26.2), app en Debug sur le serveur de dev <code>localhost:8080</code>, commerce de démo fictif « Le Petit Bistrot (démo) » (EUR, <code>help/tools/seed/seed-demo.py</code>, compte <code>bistrot.demo+devise@vendora.test</code>), appareil appairé en <strong>téléphone de salle</strong>, serveur « Lucas (salle) », « Ma session » ouverte (politique « session propre »). Addition de 32,50 € (entrecôte, crème brûlée, eau), <strong>Parts égales</strong> × 2, part 1 payée par carte.</p><table tabindex="0"><thead><tr><th>Avant (code ISO)</th><th>Après (symbole)</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="Avant : reste 16,25 EUR"></td><td><img src="'+t+'" alt="Après : reste 16,25 €"></td></tr><tr><td><img src="'+o+'" alt="Avant : addition de la table, part 1/2 encaissée"></td><td><img src="'+s+'" alt="Après : addition de la table, part 1/2 encaissée"></td></tr></tbody></table><ol><li><code>ios-01-avant-part-payee.png</code> — <strong>avant</strong> : « Table T6 · Part 1/2 — reste 16,25 EUR » (cadre).</li><li><code>ios-02-apres-part-payee.png</code> — <strong>après</strong> : « Table T5 · Part 1/2 — reste 16,25 € » (cadre).</li><li><code>ios-03-avant-addition-table.png</code> / <code>ios-04-apres-addition-table.png</code> — l&#39;addition de la table après la part (bloc « Encaissé », cadre) : déjà au bon format avant comme après (écran refondu, <code>formatMontant</code>) — seule la note de confirmation était fautive.</li></ol><p>Android : non recapturé — <code>formatMoney</code> y utilisait déjà <code>MoneyDisplay</code> ; couvert par <code>OrderPaymentViewModelTest</code> (« Table 5 · Part 1/3 — reste 66,66 € »).</p><p>Centre d&#39;aide : <code>telephone-salle/encaisser-a-la-table/04-part-payee.webp</code> refaite (elle montrait « reste 17,75 EUR »).</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-01-avant-part-payee.png" target="_blank"><img src="'+a+'" alt="ios-01-avant-part-payee.png" loading="lazy"></a><figcaption>ios-01-avant-part-payee.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-02-apres-part-payee.png" target="_blank"><img src="'+t+'" alt="ios-02-apres-part-payee.png" loading="lazy"></a><figcaption>ios-02-apres-part-payee.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-03-avant-addition-table.png" target="_blank"><img src="'+o+'" alt="ios-03-avant-addition-table.png" loading="lazy"></a><figcaption>ios-03-avant-addition-table.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-symbole-devise-parts/ios-04-apres-addition-table.png" target="_blank"><img src="'+s+'" alt="ios-04-apres-addition-table.png" loading="lazy"></a><figcaption>ios-04-apres-addition-table.png</figcaption></figure></div>',5)])])}const v=r(p,[["render",l]]);export{b as __pageData,v as default};
